// A tuple to hold user information
using UserInfo = std::tuple<std::string, std::string, std::size_t>;

// A scoped enum for the fields
enum class UserInfoFields { uiName, uiEmail, uiReputation };

void process_user_scoped(const UserInfo& uInfo) {
  // This will fail to compile due to type mismatch:
  // auto email = std::get<UserInfoFields::uiEmail>(uInfo); // ERROR

  // A verbose static_cast is required to make it work
  auto email = std::get<static_cast<std::size_t>(UserInfoFields::uiEmail)>(uInfo);
}
